import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g3-2/bot.mjs';
const run = promisify(execFile);
const now = new Date();
const dir = await mkdtemp(join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = join(dir, 'nested', 'state'); // directory does not exist yet
const bot = await import(BOT);

test('new address: marketing blocked (never opted in), receipt allowed', async () => {
  const m = await bot.mayEmail('new@example.com', 'marketing', now);
  assert.equal(m.allowed, false); assert.match(m.reason, /never opted in/);
  const r = await bot.mayEmail('new@example.com', 'receipt', now);
  assert.equal(r.allowed, true);
});

test('opt-in allows marketing; unsubscribe blocks it; receipts still allowed', async () => {
  await bot.resubscribe('Shopper@Example.com ');
  assert.equal((await bot.mayEmail('  shopper@example.COM', 'marketing', now)).allowed, true);
  await new Promise(r => setTimeout(r, 5));
  await bot.unsubscribe(' SHOPPER@example.com');
  const m = await bot.mayEmail('shopper@example.com', 'marketing', now);
  assert.equal(m.allowed, false); assert.match(m.reason, /unsubscribed/);
  assert.equal((await bot.mayEmail('shopper@example.com', 'receipt', now)).allowed, true);
});

test('resubscribe after unsubscribe re-enables marketing', async () => {
  await new Promise(r => setTimeout(r, 5));
  await bot.resubscribe('shopper@example.com');
  assert.equal((await bot.mayEmail('shopper@example.com', 'marketing', now)).allowed, true);
});

test('unsubscribe in same ms as resubscribe wins (tie = blocked)', async () => {
  const origNow = Date.now;
  Date.now = () => 1_700_000_000_000;
  try {
    await bot.resubscribe('tie@example.com');
    await bot.unsubscribe('tie@example.com');
  } finally { Date.now = origNow; }
  assert.equal((await bot.mayEmail('tie@example.com', 'marketing', now)).allowed, false);
});

test('fail closed on bad kind and bad address; invalid now throws', async () => {
  assert.equal((await bot.mayEmail('shopper@example.com', 'promo', now)).allowed, false);
  assert.equal((await bot.mayEmail('not-an-email', 'receipt', now)).allowed, false);
  await assert.rejects(bot.unsubscribe('nope'), TypeError);
  await assert.rejects(bot.mayEmail('<EMAIL>', 'marketing', 'today'), TypeError);
});

test('concurrent writers in separate processes, then fresh process sees all', async () => {
  const script = `
    const bot = await import(${JSON.stringify(BOT)});
    await bot.unsubscribe('race@example.com');
  `;
  await Promise.all(Array.from({ length: 20 }, () => run(process.execPath, ['--input-type=module', '-e', script], { env: process.env })));
  const files = await readdir(join(process.env.STATE_DIR, 'consent'));
  assert.ok(files.length >= 1);
  const { stdout } = await run(process.execPath, ['--input-type=module', '-e',
    `const b = await import(${JSON.stringify(BOT)}); console.log(JSON.stringify(await b.mayEmail(' RACE@example.com', 'marketing', new Date())));`],
    { env: process.env });
  assert.equal(JSON.parse(stdout).allowed, false);
  const entries = await readdir(join(process.env.STATE_DIR, 'consent', files[0]) );
  assert.ok(entries.every(n => !n.startsWith('.tmp-')), 'no leftover temp files');
});

test('state is shared through STATE_DIR only (in-memory state is not used)', async () => {
  const other = await mkdtemp(join(tmpdir(), 'bot-other-'));
  const { stdout } = await run(process.execPath, ['--input-type=module', '-e',
    `const b = await import(${JSON.stringify(BOT)}); console.log(JSON.stringify(await b.mayEmail('race@example.com', 'marketing', new Date())));`],
    { env: { ...process.env, STATE_DIR: other } });
  assert.equal(JSON.parse(stdout).allowed, false); // never opted in in the fresh dir
});
EOF
cd /tmp/bot-check && node --test bot.test.mjs 2>&1 | tail -40
